    static final int FALLBACK=RESULT_FIRST_USER;private static final int GENERATED=832;private String generatedRequest="";
    private String label="",hash="",nonce="",run="",route="code",error="",scanState="idle";private int unit;private MathSettings fallback=MathSettings.LEGACY,fallbackDraft=MathSettings.LEGACY;
    private String format=MorningBarcode.QR;private Dialog formatDialog;
    private MorningCode expected;private boolean challenge,resumed,wantScan,pendingPermission,settingsRequest;private QrCameraAccess.Port access;private QrCamera.Factory cameraFactory;private QrCamera.Port camera;private QrScanSession session;
    private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable verify=new Runnable(){public void run(){if(!resumed||!challenge)return;if(!current()){stopCamera();setResult(RESULT_CANCELED);finish();return;}handler.postDelayed(this,250);}};
    static Intent enroll(Activity activity,MorningCode code,String request){Intent intent=RecordUi.intent(activity,QrCodeActivity.class).putExtra("request",request);if(code!=null)try{intent.putExtra("code",MorningCodeJson.encode(code).toString());}catch(JSONException impossible){throw new IllegalStateException(impossible);}return intent;}
