    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);access=QrCameraAccess.port;cameraFactory=QrCamera.factory;challenge=getIntent().getBooleanExtra("challenge",false);nonce=getIntent().getStringExtra("request");if(nonce==null||nonce.isEmpty()){finish();return;}run=getIntent().getStringExtra("run");unit=getIntent().getIntExtra("unit",-1);
        try{if(getIntent().hasExtra("code")){expected=MorningCodeJson.decode(new JSONObject(getIntent().getStringExtra("code")));label=expected.label;hash=expected.hash;format=expected.format;fallback=expected.fallback;}if(challenge&&expected==null)throw new IllegalArgumentException("This morning code is unavailable.");if(saved!=null){generatedRequest=saved.getString("generatedRequest","");label=saved.getString("label",label);hash=saved.getString("hash",hash);format=saved.getString("format",format);if(!MorningBarcode.supported(format))throw new IllegalArgumentException("Invalid scanner format");fallback=MathSettingsJson.decode(new JSONObject(saved.getString("fallback",MathSettingsJson.encode(fallback).toString())));fallbackDraft=MathSettingsJson.decode(new JSONObject(saved.getString("fallbackDraft",MathSettingsJson.encode(fallback).toString())));route=saved.getString("route","code");error=saved.getString("error","");scanState=saved.getString("scanState","idle");wantScan=saved.getBoolean("wantScan");pendingPermission=saved.getBoolean("pendingPermission");settingsRequest=saved.getBoolean("settingsRequest");}else{fallbackDraft=fallback;wantScan=challenge;}}catch(Exception invalid){error="Morning code settings could not be read.";hash="";wantScan=false;}
        if(challenge&&expected!=null)format=expected.format;
        if(challenge){setShowWhenLocked(true);setTurnScreenOn(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){public void handleOnBackPressed(){back();}});render();
    }
    @Override protected void onResume(){super.onResume();resumed=true;if(challenge){verify.run();if(isFinishing())return;}if(wantScan&&route.equals("code")){QrCameraAccess.Status permission=access.status(this);if(permission==QrCameraAccess.Status.READY)begin();else if(!pendingPermission||settingsRequest){wantScan=false;pendingPermission=false;settingsRequest=false;scanState="idle";}}render();}
    @Override protected void onPause(){resumed=false;if(formatDialog!=null)formatDialog.dismiss();handler.removeCallbacks(verify);stopCamera();super.onPause();}
    private boolean current(){if(isFinishing()||isDestroyed())return false;if(!challenge)return resumed;try{if(run==null||!AlarmService.current(this,run)||Prefs.number(this,"challengeCompleted",-1)!=unit)return false;Alarm active=Alarm.read(new JSONObject(Prefs.text(this,"active_alarm","{}")));ChallengeRoutine.Position position=active.challenges().at(unit);return position!=null&&position.task.type.equals("QR code")&&position.task.code!=null&&expected!=null&&position.task.code.sameIdentity(expected);}catch(Exception invalid){return false;}}
    private void render(){if(route.equals("math")){fallbackScreen();return;}LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,challenge?"Scan morning code":"Add a morning code",this::back);Design.space(body,8);Design.text(body,challenge?"Find the code at "+label+".":"Place your selected code away from your bed.",14,400,Design.MUTED);Design.space(body,16);
        if(!challenge){RecordUi.segments(body,new String[]{"QR code","Barcode"},MorningBarcode.QR.equals(format)?0:1,n->selectFormat(n==0?MorningBarcode.QR:MorningBarcode.QR.equals(format)?"EAN_13":format));if(!MorningBarcode.QR.equals(format)){PlanActivity.detail(body,"qr","Barcode format",null,MorningBarcode.label(format),this::chooseFormat);Design.text(body,"Scan exactly this format. No product lookup.",12,400,Design.MUTED);}Design.space(body,12);}else Design.text(body,MorningBarcode.label(format)+" · enrolled format",12,500,Design.BROWN);
        if(!challenge){Design.text(body,"Location name",13,500,Design.MUTED);Design.space(body,6);EditText name=new EditText(this);name.setSingleLine(true);name.setHint("Bathroom");name.setContentDescription(MorningBarcode.QR.equals(format)?"QR location name":"Barcode location name");name.setText(label);name.setTextSize(16*Appearance.scale(this));name.setTypeface(Design.font(this,400));name.setTextColor(Design.INK);name.setHintTextColor(Design.MUTED);name.setBackground(Design.outline(this,Design.CREAM,Design.LINE,12));name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(60)});Design.pad(name,14,12);body.addView(name,new LinearLayout.LayoutParams(-1,-2));name.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){label=s.toString();}public void afterTextChanged(Editable value){}});Design.space(body,14);}
        if(!challenge&&MorningBarcode.QR.equals(format)){Design.item(body,"qr","Generate printable code","Create a random code · save or print",this::generate);Design.space(body,10);}
        FrameLayout frame=new FrameLayout(this);frame.setBackground(Design.shape(this,Design.SOFT,20));frame.setClipToOutline(true);frame.setContentDescription(MorningBarcode.QR.equals(format)?"QR camera preview":"Barcode camera preview");if(camera!=null&&session!=null&&session.state()==QrScanSession.State.SCANNING){View preview=camera.preview();if(preview.getParent() instanceof ViewGroup parent)parent.removeView(preview);frame.addView(preview,new FrameLayout.LayoutParams(-1,-1));frame.addView(new Reticle(this),new FrameLayout.LayoutParams(-1,-1));}else{LinearLayout empty=Design.col(this);empty.setGravity(Gravity.CENTER);Design.Icon qr=new Design.Icon(this,"qr",Design.BROWN);empty.addView(qr,new LinearLayout.LayoutParams(Design.dp(this,66),Design.dp(this,66)));Design.space(empty,14);Design.text(empty,MorningCode.validHash(hash)&&!challenge?"Code ready to save":"Camera stays off until you scan",13,500,Design.MUTED).setGravity(Gravity.CENTER);frame.addView(empty,new FrameLayout.LayoutParams(-1,-1));}body.addView(frame,new LinearLayout.LayoutParams(-1,Design.dp(this,228)));Design.space(body,9);
        if(!challenge&&MorningCode.validHash(hash)){LinearLayout status=Design.row(this);Design.pad(status,12,10);status.setBackground(Design.shape(this,0xffe3efd4,13));status.addView(new Design.Icon(this,"check",0xff16732e),new LinearLayout.LayoutParams(Design.dp(this,24),Design.dp(this,24)));TextView captured=Design.text(this,"Code captured",14,600,0xff154b19);captured.setPadding(Design.dp(this,10),0,0,0);status.addView(captured);body.addView(status);}
        else if(scanState.equals("scanning"))Design.text(body,"Point the camera at your "+MorningBarcode.label(format)+" code.",13,400,Design.MUTED);
        QrCameraAccess.Status permission=access.status(this);if(session==null||session.state()!=QrScanSession.State.SCANNING){String action=permission==QrCameraAccess.Status.NEEDED&&!challenge?"Allow camera":permission==QrCameraAccess.Status.SETTINGS&&!challenge?"Open camera settings":"Scan code";Button scan=Design.button(body,action,false,this::scanPressed);if(permission==QrCameraAccess.Status.UNSUPPORTED||challenge&&permission!=QrCameraAccess.Status.READY){scan.setEnabled(false);scan.setAlpha(.5f);Design.text(body,permission==QrCameraAccess.Status.UNSUPPORTED?"No supported camera is available.":"Camera access is off. Use your Math fallback.",12,400,Design.MUTED);}}
        if(!challenge){Design.space(body,8);PlanActivity.detail(body,"math","Fallback task","One Math question if this code cannot be scanned",fallback.level.label,()->{wantScan=false;pendingPermission=false;stopCamera();fallbackDraft=fallback;route="math";error="";render();});}
        LinearLayout footer=RecordUi.footer(body);TextView problem=Design.text(footer,error,12,500,0xffa93919);problem.setContentDescription("QR scan error");problem.setVisibility(error.isEmpty()?View.GONE:View.VISIBLE);problem.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);if(challenge)Design.button(footer,"Use Math fallback",true,()->respond(FALLBACK,null));else Design.button(footer,"Save code",true,this::save);if(challenge)Design.button(footer,"Return to challenge",false,this::back);
    }
    private void generate(){if(challenge||!resumed||!hasWindowFocus()||!MorningBarcode.QR.equals(format))return;wantScan=false;pendingPermission=false;stopCamera();if(session!=null&&!session.released()){error="Camera cleanup is still pending. Try again when it finishes.";render();return;}generatedRequest=java.util.UUID.randomUUID().toString();try{startActivityForResult(GeneratedMorningQrActivity.create(this,label,generatedRequest),GENERATED);}catch(RuntimeException unavailable){generatedRequest="";error="The printable code screen could not open. Your existing code was kept.";render();}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=GENERATED)return;String expectedRequest=generatedRequest;generatedRequest="";if(challenge||result!=RESULT_OK||data==null||expectedRequest.isEmpty())return;try{if(data.getData()!=null||data.getClipData()!=null||data.getSelector()!=null||!expectedRequest.equals(data.getStringExtra("request")))throw new IllegalArgumentException();MorningCode draft=new MorningCode(data.getStringExtra("label"),data.getStringExtra("hash"),fallback,MorningBarcode.QR);label=draft.label;hash=draft.hash;format=MorningBarcode.QR;scanState="captured";wantScan=false;pendingPermission=false;error="Printable code selected for this draft. Tap Save code, then Save alarm to apply it.";render();}catch(Exception invalid){error="Generated code result was stale or unavailable. Your existing draft code was kept.";render();}}
    private void chooseFormat(){if(challenge)return;String[] names=MorningBarcode.FORMATS.stream().map(MorningBarcode::label).toArray(String[]::new);formatDialog=SleepPicker.choices(this,"Barcode format",names,MorningBarcode.FORMATS.indexOf(format),n->selectFormat(MorningBarcode.FORMATS.get(n)));}
    private void selectFormat(String selected){if(challenge||format.equals(selected))return;wantScan=false;pendingPermission=false;stopCamera();if(session!=null&&!session.released()){error="Camera could not close. Reopen this screen before changing format.";render();return;}format=selected;hash="";scanState="idle";error="";render();}
    private void scanPressed(){if(!resumed||!current()||!hasWindowFocus()||pendingPermission)return;error="";QrCameraAccess.Status permission=access.status(this);if(permission==QrCameraAccess.Status.READY){wantScan=true;begin();return;}if(challenge){error="Camera access is off. Use your Math fallback.";render();return;}if(permission==QrCameraAccess.Status.UNSUPPORTED){error="No supported camera is available.";render();return;}pendingPermission=true;settingsRequest=permission==QrCameraAccess.Status.SETTINGS;wantScan=true;try{access.request(this);if(access.status(this)==QrCameraAccess.Status.READY&&resumed){pendingPermission=false;begin();}}catch(RuntimeException unavailable){pendingPermission=false;wantScan=false;error="Camera access settings could not open. Try Android app settings.";render();}}
    private void begin(){if(!resumed||!current()||!route.equals("code")||access.status(this)!=QrCameraAccess.Status.READY)return;pendingPermission=false;settingsRequest=false;if(session!=null){session.close();if(!session.released()){wantScan=false;error="Camera could not close. Reopen this screen before scanning again.";render();return;}session=null;camera=null;}try{camera=cameraFactory.create(this,format);session=new QrScanSession(camera,new QrScanSession.Effects(){public boolean current(){return resumed&&route.equals("code")&&QrCodeActivity.this.current();}public void captured(String captured){wantScan=false;if(access.status(QrCodeActivity.this)!=QrCameraAccess.Status.READY){scanState="error";error="Camera access changed. Allow access before scanning again.";render();return;}scanState="captured";if(challenge){if(expected!=null&&MorningCode.same(expected.hash,captured)){respond(RESULT_OK,captured);return;}error="That is not your enrolled morning code. Try again or use Math fallback.";}else{hash=captured;error="";}render();}public void error(String reason){wantScan=false;scanState="error";error=reason;render();}});scanState="scanning";session.start();render();}catch(RuntimeException unavailable){wantScan=false;scanState="error";stopCamera();error="Camera could not start. Check access and try again.";render();}}
    private void stopCamera(){if(session!=null){session.close();if(session.released()){session=null;camera=null;}}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==QrCameraAccess.REQUEST){boolean owned=pendingPermission&&wantScan&&!challenge&&route.equals("code")&&!isFinishing()&&!isDestroyed();pendingPermission=false;settingsRequest=false;if(!owned)return;if(access.status(this)==QrCameraAccess.Status.READY){if(resumed)begin();}else{wantScan=false;error="Camera access was not allowed. You can keep editing and try again later.";render();}}}
    private void save(){wantScan=false;pendingPermission=false;stopCamera();if(session!=null&&!session.released()){error="Camera could not close. Reopen this screen before saving.";render();return;}try{MorningCode code=new MorningCode(label,hash,fallback,format);setResult(RESULT_OK,new Intent().putExtra("request",nonce).putExtra("code",MorningCodeJson.encode(code).toString()));finish();}catch(Exception invalid){error=invalid.getMessage()==null?"Capture a code and name its location first.":invalid.getMessage();render();}}
    private void respond(int result,String scanned){if(!challenge||!current()){setResult(RESULT_CANCELED);finish();return;}wantScan=false;stopCamera();Intent data=new Intent().putExtra("request",nonce).putExtra("run",run).putExtra("unit",unit).putExtra("format",format);if(scanned!=null)data.putExtra("hash",scanned);setResult(result,data);finish();}
    private void fallbackScreen(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Fallback task",this::back);Design.space(body,12);Design.text(body,"Math complexity",15,600,Design.INK);Design.space(body,10);RecordUi.segments(body,new String[]{"Easy","Medium","Hard"},fallbackDraft.level.ordinal(),n->{fallbackDraft=new MathSettings(MathSettings.Level.values()[n],fallbackDraft.operators,fallbackDraft.typed);error="";render();});Design.space(body,8);Design.text(body,fallbackDraft.explanation(),12,400,Design.MUTED);Design.space(body,16);Design.text(body,"Operators",15,600,Design.INK);Design.space(body,8);MathOperatorGrid.add(body,fallbackDraft,next->{fallbackDraft=next;error="";render();},()->{error="Keep at least one fallback operator selected.";render();});Design.space(body,10);Design.text(body,"Answer method",15,600,Design.INK);Design.space(body,8);RecordUi.segments(body,new String[]{"Choices","Type answer"},fallbackDraft.typed?1:0,n->{fallbackDraft=new MathSettings(fallbackDraft.level,fallbackDraft.operators,n==1);render();});LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty())Design.text(footer,error,12,500,0xffa93919);Design.button(footer,"Use fallback",true,()->{fallback=fallbackDraft;route="code";error="";render();});}
    private void back(){if(route.equals("math")){fallbackDraft=fallback;route="code";error="";render();return;}wantScan=false;pendingPermission=false;stopCamera();setResult(RESULT_CANCELED);finish();}
    @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putString("generatedRequest",generatedRequest);saved.putString("label",label);saved.putString("hash",hash);saved.putString("format",format);saved.putString("route",route);saved.putString("error",error);saved.putString("scanState",scanState);saved.putBoolean("wantScan",wantScan);saved.putBoolean("pendingPermission",pendingPermission);saved.putBoolean("settingsRequest",settingsRequest);try{saved.putString("fallback",MathSettingsJson.encode(fallback).toString());saved.putString("fallbackDraft",MathSettingsJson.encode(fallbackDraft).toString());}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(formatDialog!=null)formatDialog.dismiss();stopCamera();super.onDestroy();}
    private static final class Reticle extends View {
        private final android.graphics.Paint paint=new android.graphics.Paint(3);private final android.graphics.Path corners=new android.graphics.Path();
        Reticle(Context c){super(c);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);paint.setColor(android.graphics.Color.WHITE);paint.setStrokeWidth(4*getResources().getDisplayMetrics().density);paint.setStrokeCap(android.graphics.Paint.Cap.ROUND);paint.setStyle(android.graphics.Paint.Style.STROKE);}
        @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);float pad=Math.min(w,h)*.2f,l=pad,t=pad,r=w-pad,b=h-pad,arm=22*getResources().getDisplayMetrics().density;corners.reset();for(float[] line:new float[][]{{l,t,l+arm,t},{l,t,l,t+arm},{r,t,r-arm,t},{r,t,r,t+arm},{l,b,l+arm,b},{l,b,l,b-arm},{r,b,r-arm,b},{r,b,r,b-arm}}){corners.moveTo(line[0],line[1]);corners.lineTo(line[2],line[3]);}}
        @Override protected void onDraw(android.graphics.Canvas canvas){canvas.drawPath(corners,paint);}
    }
